void Earcut<N>::operator()(const Polygon& points) {
    indices.clear();
    vertices = 0;

    if (points.empty()) return;

    double x, y;
    threshold = 80;
    std::size_t len = 0;

    for (const auto& ring : points) {
        len += ring.size();
