template <typename Ring>
typename Earcut<N>::Node*
Earcut<N>::linkedList(const Ring& points, const bool clockwise) {
    using Point = typename Ring::value_type;
    double sum = 0;
    const std::size_t len = points.size();
    std::size_t i = 0, j = len > 0 ? len - 1 : 0;
    Node* last = nullptr;

    // calculate original winding order of a polygon ring
    for (; i < len; j = i++) {
        const auto& p1 = points[i];
        const auto& p2 = points[j];
        const double p20 = p2[0];
        const double p10 = p1[0];
        const double p11 = p1[1];
        const double p21 = p2[1];
        sum += (p20 - p10) * (p11 + p21);
    }

    // link points into circular doubly-linked list in the specified winding order
    if (clockwise == (sum > 0)) {
        for (i = 0; i < len; i++) last = insertNode(vertices + i, points[i][0], points[i][1], last);
    } else {
        for (i = len; i-- > 0;) last = insertNode(vertices + i, points[i][0], points[i][1], last);
    }

    if (last && equals(last, last->next)) {
        removeNode(last);
        last = last->next;
    }

    vertices += len;

    return last;
}
