fn insert_node(&mut self, i: u32, x: f64, y: f64, last: usize) -> usize {
    let p = self.create_node(i, x, y);
    if last == NULL {
        self.nodes[p].prev = p;
        self.nodes[p].next = p;
    } else {
        let lnext = self.nodes[last].next;
        self.nodes[p].next = lnext;
        self.nodes[p].prev = last;
        self.nodes[lnext].prev = p;
        self.nodes[last].next = p;
    }
    p
}
