fn index_curve(&mut self, start: usize) {
    let mut p = start;
    loop {
        if self.nodes[p].z == 0 { self.nodes[p].z = self.z_order(self.nodes[p].x, self.nodes[p].y); }
        self.nodes[p].prev_z = self.nodes[p].prev;
