                a = self.filter_points(a, self.nodes[a].next);
                let c2 = self.filter_points(c, self.nodes[c].next);
                self.earcut_linked(a, 0);
                self.earcut_linked(c2, 0);
                return;
            }
            b = self.nodes[b].next;
        }
        a = self.nodes[a].next;
        if a == start { break; }
    }
}
