Careful: std::atoi parses leading whitespace, optional sign, digits, stops at first non-digit; returns 0 if none. Rust parse::<i32> would fail on "12abc". Implement atoi semantics:

```rust
fn atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && (bytes[i] as char).is_whitespace() { i += 1; }
    // C isspace: ' ', \t, \n, \v, \f, \r
    let mut sign = 1i64;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        if bytes[i] == b'-' { sign = -1; }
        i += 1;
    }
    let mut val: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        val = val * 10 + (bytes[i] - b'0') as i64;
        i += 1;
    }
    (sign * val) as i32  // atoi overflow is UB; just wrap
}
